def pill(text):
    return f'<span style="display:inline-block;border:1px solid currentColor;padding:.55em .85em;margin:.25em .35em .25em 0;font-family:var(--mono);font-size:max(12px,.85vw);letter-spacing:.08em">{text}</span>'
def card(label,title,body,small=None):
    s=f'<div style="border-top:1px solid currentColor;padding:1.6vh 1.3vw;display:flex;flex-direction:column;gap:1.1vh"><div class="meta">{label}</div><h3 class="h-md h-xl-en" style="font-size:2vw">{title}</h3><p class="body-zh">{body}</p>'
    if small:s+=f'<div class="meta" style="margin-top:auto;padding-top:.8vh">{small}</div>'
    return s+'</div>'
def imagefig(key,caption):
    return f'<figure class="frame-img r-16x10 fit-contain" style="max-height:53vh;background:var(--paper);padding:.6vw;border:1px solid rgba(var(--ink-rgb),.16)"><img src="{img[key]}" alt="{html.escape(caption,quote=True)}" style="width:100%;height:100%;object-fit:contain"><figcaption class="img-cap">{caption}</figcaption></figure>'
def mk(id,title,kicker,theme,body,chapter,foot,hero=False,notespec=None):
    i=len(slides)+1
    cls=('slide hero '+theme) if hero else ('slide '+theme)
    title_html=f'<h2 class="h-xl h-xl-en" data-anim style="font-size:min(4.8vw,8.4vh);max-width:86vw">{title}</h2>'
    if hero:
        title_html=f'<h1 class="h-hero h-hero-en" data-anim style="font-size:min(8vw,14vh);line-height:.98;max-width:84vw">{title}</h1>'
    section=f'''<section class="{cls}" data-slide-id="{id}" data-animate="{'hero' if hero else 'cascade'}">
<div class="chrome"><div class="left"><span>GLOH 520</span><span class="sep"></span><span>Health Financing</span></div><div class="right"><span>{i:02d} / {N:02d}</span></div></div>
<div class="kicker" data-anim style="margin-top:{'8vh' if hero else '3.2vh'}">{kicker}</div>{title_html}
<div class="frame" style="padding-top:{'5vh' if hero else '3.4vh'};min-height:0">{body}</div>
<div class="foot"><div class="title">{foot}</div><div>{chapter} · {i:02d}</div></div>
</section>'''
    slides.append(section)
    if notespec is None: notespec={}
    notes.append({'id':id,'title':re.sub('<[^>]+>','',title).replace('<br>',' '),'section':chapter,'purpose':notespec.get('purpose',f'Explain the central point of this page using the source lecture content.'),'talk':notespec.get('talk',['Keep the emphasis on the source content represented here.','Connect the example or framework to the wider UHC discussion.','Invite the audience to notice the relationship shown on the page.']),'transition':notespec.get('transition','Use this point to move from the current concept to the next question.')})

