colors=['rgba(var(--ink-rgb),.92)','rgba(var(--ink-rgb),.72)','rgba(var(--ink-rgb),.49)','rgba(var(--ink-rgb),.33)','rgba(var(--ink-rgb),.20)','rgba(var(--ink-rgb),.10)']
